    P.same("Vector3 * Basis", (self * b), P.op(P.Op.Multiply, P.v(self), P.v(b)).as[Vector3])
  }

  private def o_21(r: P.Rng): String = {
    val self = P.vector3(r)
    val b = P.transform3D(r)
    P.same("Vector3 * Transform3D", (self * b), P.op(P.Op.Multiply, P.v(self), P.v(b)).as[Vector3])
  }
}
